#include <stdexcept>

constexpr int digit(char c) {
  if (c < '0' || c > '9') throw std::invalid_argument("not a digit");
  return c - '0';
}

constexpr int digit_or(char c, int fallback) {
  try { return digit(c); }
  catch (const std::invalid_argument&) { return fallback; }
}

static_assert(digit_or('x', -1) == -1);

int main() {}

